// One-off script: writes RecipeTranslation rows (locale "es") for every
// currently-active recipe, generated by hand/LLM translation (see the
// es-translations-*.json batch files this reads, merged from
// /tmp/.../scratchpad/es-batch-{1..4}.json during generation). Run once;
// re-running is safe (upsert) but will only ever write es, and only for
// recipe ids present in the merged translations file.
import { PrismaClient } from "@prisma/client";
import fs from "fs";

const prisma = new PrismaClient();

async function main() {
  const translations = JSON.parse(
    fs.readFileSync(new URL("./es-translations.json", import.meta.url), "utf8"),
  );

  const recipes = await prisma.recipe.findMany({
    where: { id: { in: Object.keys(translations) } },
    select: { id: true, contentVersion: true },
  });
  const contentVersionById = new Map(recipes.map((r) => [r.id, r.contentVersion]));

  let written = 0;
  for (const [recipeId, t] of Object.entries(translations)) {
    const contentVersion = contentVersionById.get(recipeId);
    if (contentVersion === undefined) {
      console.warn(`Skipping ${recipeId}: no matching active recipe found.`);
      continue;
    }
    await prisma.recipeTranslation.upsert({
      where: { recipeId_locale: { recipeId, locale: "es" } },
      create: {
        recipeId,
        locale: "es",
        title: t.title,
        shortDescription: t.shortDescription,
        note: t.note,
        introCopy: t.introCopy,
        pairingSuggestion: t.pairingSuggestion ?? null,
        ingredients: t.ingredients,
        steps: t.steps,
        sourceContentVersion: contentVersion,
      },
      update: {
        title: t.title,
        shortDescription: t.shortDescription,
        note: t.note,
        introCopy: t.introCopy,
        pairingSuggestion: t.pairingSuggestion ?? null,
        ingredients: t.ingredients,
        steps: t.steps,
        sourceContentVersion: contentVersion,
      },
    });
    written++;
  }
  console.log(`Wrote ${written} Spanish RecipeTranslation rows.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
